module Ripple_Carry_Adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);

    // Overall output matches 4-bit addition with carry in.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // Bit 0 sum is the XOR of A[0], B[0], and Cin.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 1 sum uses the carry generated by bit 0.
    check_bit1_sum: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))))
    );

    // Bit 2 sum uses the carry out of the lower two bits.
    check_bit2_sum: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ (({1'b0, A[1:0]} + {1'b0, B[1:0]} + Cin) >= 3'd4))
    );

    // Bit 3 sum uses the carry out of the lower three bits.
    check_bit3_sum: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ (({1'b0, A[2:0]} + {1'b0, B[2:0]} + Cin) >= 4'd8))
    );

    // Cout is the carry out of the full 4-bit addition.
    check_cout_consistency: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16)
    );

    // Zero plus zero with no carry in produces zero.
    check_zero_addition: assert property (
        @(posedge clk) ((A == 4'd0) && (B == 4'd0) && (Cin == 1'b0)) |-> ({Cout, S} == 5'd0)
    );

    // Adding zero on B with no carry in passes A through.
    check_add_zero_rhs: assert property (
        @(posedge clk) ((B == 4'd0) && (Cin == 1'b0)) |-> ({Cout, S} == {1'b0, A})
    );

    // Adding zero on A with no carry in passes B through.
    check_add_zero_lhs: assert property (
        @(posedge clk) ((A == 4'd0) && (Cin == 1'b0)) |-> ({Cout, S} == {1'b0, B})
    );

    // With B at zero, Cin increments A by one.
    check_increment_with_cin: assert property (
        @(posedge clk) ((B == 4'd0) && (Cin == 1'b1)) |-> ({Cout, S} == ({1'b0, A} + 5'd1))
    );

endmodule